import{d,C as n,o as s,c as m,E as t,a3 as a}from"./chunks/framework.D4-ViStF.js";const c=JSON.parse('{"title":"蒙卦","description":"第四卦·山水蒙——山下有险，蒙以养正。","frontmatter":{"title":"蒙卦","description":"第四卦·山水蒙——山下有险，蒙以养正。","category":"hexagram","aliases":["蒙","山水蒙"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-04.md","filePath":"yijing/hexagrams/hexagram-04.md","lastUpdated":1787730063000}'),h={name:"yijing/hexagrams/hexagram-04.md"},x=d({...h,setup(u){const r=[{id:"fameng",term:"发蒙",pinyin:"fā méng",meaning:"启发蒙昧。初六进入蒙境，第一步是让蒙「显现」出来——看见自己在蒙。"},{id:"xingren",term:"刑人",pinyin:"xíng rén",meaning:"用规矩、惩戒来约束。规矩与边界是发蒙的工具，不是目的。"},{id:"zhigu",term:"桎梏",pinyin:"zhì gù",meaning:"枷锁、刑具（桎为脚镣，梏为手铐）。「用说桎梏」即解脱束缚。"},{id:"shuo",term:"说",pinyin:"tuō",meaning:"通「脱」，解脱、放开。「用说桎梏」即脱去枷锁。"},{id:"baomeng",term:"包蒙",pinyin:"bāo méng",meaning:"包容蒙昧。九二是蒙卦真正的「师」，能装得下各种蒙昧。"},{id:"nafu",term:"纳妇",pinyin:"nà fù",meaning:"迎纳、接纳。「纳妇吉」喻能容、能纳。"},{id:"zikejia",term:"子克家",pinyin:"zǐ kè jiā",meaning:"儿子能承担家业。喻有担当、能成事。"},{id:"jinfu",term:"金夫",pinyin:"jīn fū",meaning:"强壮、光鲜的外在，喻权势、财富、表象。「见金夫」即只追外在光鲜。"},{id:"buyougong",term:"不有躬",pinyin:"bù yǒu gōng",meaning:"失去自身的主体性，不能自持。"},{id:"kunmeng",term:"困蒙",pinyin:"kùn méng",meaning:"困在蒙昧之中。「困」字形：木在口中——还在生长，但口从未打开。"},{id:"tongmeng",term:"童蒙",pinyin:"tóng méng",meaning:"孩童般的蒙昧，白纸、空杯，能容纳。"},{id:"jimeng",term:"击蒙",pinyin:"jī méng",meaning:"以强力破除蒙昧，最后一击。"},{id:"weikou",term:"为寇",pinyin:"wéi kòu",meaning:"以武力征服蒙昧，出发点是要消灭对方的无知——自己成了新的蒙。"},{id:"yukou",term:"御寇",pinyin:"yù kòu",meaning:"守护、抵御蒙昧的侵蚀，出发点是守护。"},{id:"yizhengfa",term:"以正法",pinyin:"yǐ zhèng fǎ",meaning:"以端正法度。利用刑人，是为了正法，不是为了惩罚。"},{id:"gangroujie",term:"刚柔接",pinyin:"gāng róu jiē",meaning:"刚柔相接。子克家，因刚柔相接——有实力而不傲。"},{id:"xingbushun",term:"行不顺",pinyin:"xíng bù shùn",meaning:"行为不顺于正道。勿用取女，因其行不顺。"},{id:"duyuanshi",term:"独远实",pinyin:"dú yuǎn shí",meaning:"独自远离真实（阳实）。困蒙之吝，因为远离了实，无路可通。"},{id:"shunyixun",term:"顺以巽",pinyin:"shùn yǐ xùn",meaning:"顺从而谦逊。童蒙之吉，在于能顺能巽。"},{id:"shangxiashun",term:"上下顺",pinyin:"shàng xià shùn",meaning:"上下和顺。以御寇去击蒙，则上下皆顺。"}],e=[{position:"初六",type:"yin",text:"发蒙，利用刑人，用说桎梏，以往吝。",xiang:"利用刑人，以正法也。",textModern:"发蒙的第一步，是让蒙「显现」出来——看见自己在蒙。规矩与边界是工具，不是目的；若只靠外部约束、不知为何而行，走下去会有憾惜。",xiangModern:"用规矩约束，是为了端正法度、立起边界，而不是为了惩罚。"},{position:"九二",type:"yang",text:"包蒙，吉。纳妇，吉。子克家。",xiang:"子克家，刚柔接也。",textModern:"能包容各种蒙昧，吉祥；能接纳、能承担，吉祥；像儿子能承担家业一样，是真正有担当的发蒙者。",xiangModern:"能承担家业，是因为刚柔相接——有实力而不傲，上承君位、下化众阴。"},{position:"六三",type:"yin",text:"勿用取女，见金夫，不有躬，无攸利。",xiang:"勿用取女，行不顺也。",textModern:"见到强壮的「金夫」就扑过去，不守自身、只追外在光鲜；这种投机求蒙，没有任何真实收获。",xiangModern:"不要迎娶这样的女子，是因为她的行为不顺于正道——只为攀附而学。"},{position:"六四",type:"yin",text:"困蒙，吝。",xiang:"困蒙之吝，独远实也。",textModern:"困在蒙昧里，却感觉良好、口已关死；努力在既定边界内循环，而非突破，留下结构性的遗憾。",xiangModern:"困蒙的憾惜，在于独自远离了真实（阳实），无人可依、无路可通。"},{position:"六五",type:"yin",text:"童蒙，吉。",xiang:"童蒙之吉，顺以巽也。",textModern:"君位上坐着一个孩子——白纸、空杯，空才能装；居高位而能说出「我还不懂」，是最难的修行，也是最大的吉。",xiangModern:"童蒙的吉，在于能顺从而谦逊——上有上九可从，下有九二可学，双向皆通。"},{position:"上九",type:"yang",text:"击蒙，不利为寇，利御寇。",xiang:"利用御寇，上下顺也。",textModern:"最后一击，一念定性。以征服出发去消灭蒙昧，自己就成了新的蒙；以守护出发去抵挡蒙昧侵蚀，才利。",xiangModern:"以守护（御寇）而不是征服（为寇）去击蒙，则上下皆顺。"}];return(p,i)=>{const o=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),g=n("DaoKeywordCards");return s(),m("div",null,[t(o,{name:"蒙",fullName:"山水蒙",upper:"☶",lower:"☵",guaCi:"蒙，亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。",pinyin:["méng"],element:"土",direction:"东北",insight:"山下有险，蒙昧未开；蒙而知蒙，路就通了。",guaSlug:"04shanshuimeng",lines:e}),i[0]||(i[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>山下出泉，蒙。君子以果行育德。</p><p>上艮为山，下坎为水，水从山下流出，是泉之初涌、蒙昧未开之象。君子由此悟到，要以<strong>果决的行动</strong>去<strong>涵养德性</strong>——「果行」是行动果决，像泉水冲破阻碍、不停滞；「育德」是德性涵养，像泉水润物、慢慢滋养。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>蒙，山下有险，险而止，蒙。蒙亨，以亨行时中也。匪我求童蒙，童蒙求我，志应也。初筮告，以刚中也。再三渎，渎则不告，渎蒙也。蒙以养正，圣功也。</p><p>逐句释义：</p><ul><li><strong>蒙，山下有险，险而止，蒙</strong> —— 山下有险阻，遇险而停止，这就是蒙。</li><li><strong>蒙亨，以亨行时中也</strong> —— 蒙而能亨通，是因为顺着时中之道而行。</li><li><strong>匪我求童蒙，童蒙求我，志应也</strong> —— 不是我去求蒙童，是蒙童来求我，这是心志相应。</li><li><strong>初筮告，以刚中也</strong> —— 初次占问就告知，是因为九二刚健中正。</li><li><strong>再三渎，渎则不告，渎蒙也</strong> —— 再三占问就是亵渎，亵渎就不再告知，因为亵渎了蒙。</li><li><strong>蒙以养正，圣功也</strong> —— 以蒙昧涵养正道，是圣人的功业。</li></ul><blockquote><p><strong>蒙的核心</strong>：蒙，不是罪，是起点。蒙而知蒙，路是通的（亨）；最危险的蒙，是「不知道自己在蒙」。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',9)),t(l,{element:"土",guaSlug:"04shanshuimeng",glossary:r,items:e}),i[1]||(i[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-发蒙-利用刑人-用说桎梏-以往吝" tabindex="-1">初六 · 发蒙，利用刑人，用说桎梏，以往吝 <a class="header-anchor" href="#初六-·-发蒙-利用刑人-用说桎梏-以往吝" aria-label="Permalink to &quot;初六 · 发蒙，利用刑人，用说桎梏，以往吝&quot;">​</a></h3><ul><li>位置：最底，刚入蒙境，阴爻居初</li><li><strong>发蒙的第一步</strong>：让蒙「显现」出来——看见自己在蒙</li><li><strong>规矩与边界（刑人）</strong>：是发蒙的工具，不是目的</li><li>若只靠外部约束驱动，不知为何而行，走下去则吝</li></ul><blockquote><p>看见自己在蒙，是一切的开始。</p></blockquote><h3 id="九二-·-包蒙-吉。纳妇-吉。子克家" tabindex="-1">九二 · 包蒙，吉。纳妇，吉。子克家 <a class="header-anchor" href="#九二-·-包蒙-吉。纳妇-吉。子克家" aria-label="Permalink to &quot;九二 · 包蒙，吉。纳妇，吉。子克家&quot;">​</a></h3><ul><li>位置：下卦之中，全卦核心阳爻，刚中</li><li><strong>九二是蒙卦真正的「师」</strong>：全卦发蒙的核心</li><li><strong>「包」</strong>：不是包庇，是包容，能装得下各种蒙昧</li><li>刚而能柔，有实力而不傲，上承君位，下化众阴</li><li>纳妇、子克家：能承担、能成事</li></ul><blockquote><p>真正的发蒙者，是能包容一切蒙昧的人。</p></blockquote><h3 id="六三-·-勿用取女-见金夫-不有躬-无攸利" tabindex="-1">六三 · 勿用取女，见金夫，不有躬，无攸利 <a class="header-anchor" href="#六三-·-勿用取女-见金夫-不有躬-无攸利" aria-label="Permalink to &quot;六三 · 勿用取女，见金夫，不有躬，无攸利&quot;">​</a></h3><ul><li>位置：下卦之顶，阴爻居阳位，不正</li><li>见到强壮的「金夫」就扑过去，不守自身，只追外在光鲜</li><li>这种「求蒙」是功利的求、投机的求——为了攀附而学</li><li><strong>不有躬</strong>：失去了自身的主体性</li><li><strong>无攸利</strong>：没有任何真实的收获</li></ul><blockquote><p>求学若只为攀附，得到的不是发蒙，是另一种蒙。</p></blockquote><h3 id="六四-·-困蒙-吝" tabindex="-1">六四 · 困蒙，吝 <a class="header-anchor" href="#六四-·-困蒙-吝" aria-label="Permalink to &quot;六四 · 困蒙，吝&quot;">​</a></h3><ul><li>位置：上卦之底，阴爻居阴位，看似得位</li><li><strong>「困」字形</strong>：木在口中——还在生长，但口从未打开</li><li>六四的危险：不知道自己被困，感觉良好，路却关死了</li><li>困蒙不是不努力，是努力在既定边界内循环，而非突破</li><li><strong>「吝」</strong>：不是惩罚，是结构性的遗憾——在某一刻选择了「感觉良好」，关上了那条缝隙</li></ul><p><strong>与六五的对照</strong>：同样是蒙，六四「感觉已经懂了」，六五「知道自己还不懂」——一个关死了口，一个口还开着。</p><blockquote><p>困蒙之吝，不在于不努力，在于不再怀疑。</p></blockquote><h3 id="六五-·-童蒙-吉" tabindex="-1">六五 · 童蒙，吉 <a class="header-anchor" href="#六五-·-童蒙-吉" aria-label="Permalink to &quot;六五 · 童蒙，吉&quot;">​</a></h3><ul><li>位置：君位（五爻），阴爻居五，以柔居尊</li><li>君位上坐的，是一个孩子——白纸，空杯</li><li><strong>童蒙之吉</strong>：不在于聪明，在于「空」——空才能装</li><li>上有上九可从（有师），下有九二可学（有源），双向皆通</li><li>成人之蒙危险，因为认知茧房根深蒂固、有防御机制；童蒙无防御，说得出「我不知道」</li></ul><blockquote><p>居高位而能童蒙，是最难的修行，也是最大的吉。</p></blockquote><h3 id="上九-·-击蒙-不利为寇-利御寇" tabindex="-1">上九 · 击蒙，不利为寇，利御寇 <a class="header-anchor" href="#上九-·-击蒙-不利为寇-利御寇" aria-label="Permalink to &quot;上九 · 击蒙，不利为寇，利御寇&quot;">​</a></h3><ul><li>位置：全卦最高，阳爻居极，物极必反</li><li>上九是全卦最后一击，没有退路，一念定性</li><li><strong>「为寇」</strong>：以武力征服蒙昧，出发点是「我要消灭你的无知」——自己成了新的蒙</li><li><strong>「御寇」</strong>：守护抵御，帮对方抵挡蒙昧的侵蚀——出发点是守护</li><li>同一把戒尺，方向不同，性质天壤之别</li></ul><blockquote><p>击蒙者，先问自己是在守护还是在征服。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',21)),t(g,{title:"字词释义",items:[{term:"蒙",pinyin:["méng"],meaning:"蒙昧、不明。蒙不是罪，是起点。"},{term:"发蒙",pinyin:["fā","méng"],meaning:"启发蒙昧。第一步是看见自己在蒙。"},{term:"包蒙",pinyin:["bāo","méng"],meaning:"包容蒙昧。能装得下各种蒙昧。"},{term:"困蒙",pinyin:["kùn","méng"],meaning:"困在蒙昧里。「困」：木在口中，口未打开。"},{term:"童蒙",pinyin:["tóng","méng"],meaning:"孩童般的蒙昧，白纸空杯，能容纳。"},{term:"击蒙",pinyin:["jī","méng"],meaning:"以强力破除蒙昧，最后一击。"},{term:"刑人",pinyin:["xíng","rén"],meaning:"用规矩惩戒约束。发蒙的工具，不是目的。"},{term:"桎梏",pinyin:["zhì","gù"],meaning:"枷锁刑具（桎脚镣、梏手铐）。「说桎梏」即解脱束缚。"},{term:"金夫",pinyin:["jīn","fū"],meaning:"强壮光鲜的外在，喻权势、财富、表象。"},{term:"筮",pinyin:["shì"],meaning:"用蓍草占问。初筮告：真诚地问，才有真实的答。"},{term:"渎",pinyin:["dú"],meaning:"亵渎、不敬。再三渎：反复试探是对学习的亵渎。"},{term:"果行育德",pinyin:["guǒ","xíng","yù","dé"],meaning:"果决地行动、涵养德性。象传的核心。"}]}),i[2]||(i[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>蒙卦讲的是<strong>蒙昧与发蒙</strong>。上艮（山）压着下坎（水、险），山下有险、遇险而止，正是蒙昧未开之象。</p><p>卦辞「蒙亨，匪我求童蒙，童蒙求我」点明：蒙而知蒙，路是通的；是蒙者求师，不是师追蒙者。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>蒙不是罪，是起点。最危险的蒙，不是「无知」，而是「不知道自己在蒙」——六四困蒙之所以吝，不是因为不努力，而是因为不再怀疑。</p><p>发蒙的核心，是保持那条「我可能还不懂」的缝隙；发蒙的方向，是御寇（守护），而非为寇（征服）。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>先承认蒙：看见自己在蒙，是发蒙的第一步</li><li>找对方向：是「童蒙求我」，主动求教，而不是被推着走</li><li>真诚发问：初筮告——真诚地问，才有真实的答，反复试探是对学习的亵渎</li><li>守住童蒙之心：居高位而能说「我还不懂」，空才能装</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六爻总览：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>状态</th><th>结果</th></tr></thead><tbody><tr><td>初六</td><td>发蒙</td><td>看见蒙，立规矩</td><td>以往吝</td></tr><tr><td>九二</td><td>包蒙</td><td>能容蒙，真正的师</td><td>吉</td></tr><tr><td>六三</td><td>勿用取女</td><td>投机求蒙，攀附外力</td><td>无攸利</td></tr><tr><td>六四</td><td>困蒙</td><td>感觉良好，口已关死</td><td>吝</td></tr><tr><td>六五</td><td>童蒙</td><td>居高位而能空杯</td><td>吉</td></tr><tr><td>上九</td><td>击蒙</td><td>最后一击，一念定性</td><td>利御寇</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>关于蒙</strong>——蒙不是罪，是起点；蒙而知蒙，路是通的；最危险的蒙，是不知道自己在蒙</li><li><strong>关于发蒙</strong>——发蒙的前提是承认蒙；核心是保持「我可能还不懂」的缝；方向是御寇而非为寇</li><li><strong>关于困蒙</strong>——困蒙不是懒惰，是停止怀疑；感觉良好的那一刻，往往是困蒙的开始</li><li><strong>关于童蒙</strong>——童蒙之吉在于空；说得出「我不知道」是最难也最重要的能力</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>蒙卦描绘了一条完整的「蒙昧与发蒙」的生命轨迹：</p><p>初六（发蒙）→ 九二（包蒙）→ 六三（迷途）→ 六四（困蒙）→ 六五（童蒙）→ 上九（击蒙）</p><ol><li>初六：进入蒙境，先看见自己在蒙</li><li>九二：遇见真正的师，被包容、被引导</li><li>六三：岔路口——投机取巧，攀附外力，走偏了</li><li>六四：另一个陷阱——感觉良好，实则困死</li><li>六五：真正的吉——居高位而保持童蒙之心</li><li>上九：最终一击——守护还是征服，一念之间</li></ol><p><strong>一句话收整卦</strong>：蒙卦教的，不是如何变聪明；蒙卦教的，是如何保持那条缝——那条「我可能还不懂」的缝。缝在，路就在；缝关死，无论多努力，都是困蒙。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：屯（第三卦）、需（第五卦）</li><li>屯与蒙的连结：屯而后蒙——草昧之后，是启蒙；根扎稳了，才能真正开始学</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',21))])}}});export{c as __pageData,x as default};
